window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[214]={"id":"214","numero":214,"titre":"Thrombopénie chez l'adulte et l'enfant","objectifs":[{"id":"214-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une thrombopénie","contenu":"<p>Une <span class=\"kw-def\">thrombopénie</span> se définit par un nombre de <span class=\"kw-bio\">plaquettes</span> circulantes <span class=\"kw-chiffre\">&lt; 150 G/L</span>, <strong>quel que soit l'âge</strong>. Certains groupes d'experts retiennent le seuil de <span class=\"kw-chiffre\">100 G/L</span> : un chiffre situé entre <span class=\"kw-chiffre\">100 et 150 G/L</span> peut en effet être <strong>physiologique</strong> dans certaines populations (sujets d'origine orientale ou africaine).</p>\n      <p>La <span class=\"kw-clinique\">profondeur</span> oriente le risque <span class=\"kw-etio\">hémorragique</span>, mais l'importance des signes cliniques n'est <em>pas strictement corrélée</em> à la numération.</p>\n      <table >\n        <thead><tr><th>Numération plaquettaire</th><th><span class=\"kw-ci\">Risque hémorragique</span> spontané</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&gt; 50 G/L</span></td><td>Saignements spontanés <strong>exceptionnels</strong> — patient le plus souvent asymptomatique (sauf thrombopathie associée : <span class=\"kw-ci\">insuffisance rénale</span>, médicaments)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">20 – 50 G/L</span></td><td>Signes hémorragiques <strong>rares</strong>, sauf facteur surajouté</td></tr>\n          <tr><td><span class=\"kw-alerte\">&lt; 20 G/L</span></td><td>Thrombopénie souvent <strong>symptomatique</strong> — <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span> fréquent</td></tr>\n        </tbody>\n      </table>\n      <p>En présence d'un <span class=\"kw-clinique\">syndrome hémorragique</span>, la <span class=\"kw-bio\">NFS</span> montre le plus souvent un taux <span class=\"kw-alerte\">&lt; 20 G/L</span>.</p>","frequence":0},{"id":"214-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes de thrombopénie","contenu":"<p>Une thrombopénie relève de <strong>trois grands mécanismes</strong>, dont la distinction conditionne toute la démarche étiologique. Le <span class=\"kw-imagerie\">myélogramme</span> est l'examen pivot qui sépare origine centrale et périphérique.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Définition</th><th>Exemples étiologiques</th><th>Moelle (myélogramme)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Central</span></td>\n            <td>Défaut de <strong>production</strong> médullaire — souvent associé à <strong>d'autres cytopénies</strong></td>\n            <td><span class=\"kw-etio\">Envahissement médullaire</span><br><span class=\"kw-etio\">Myélodysplasie</span> ; <span class=\"kw-etio\">aplasie</span><br><span class=\"kw-etio\">Carences B9/B12</span> ; <span class=\"kw-etio\">alcoolisme chronique</span></td>\n            <td>Mégacaryocytes <strong>absents ou dysmorphiques</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Périphérique — consommation</span></td>\n            <td><span class=\"kw-bio\">Plaquettes</span> produites normalement mais <strong>consommées</strong> en excès</td>\n            <td><span class=\"kw-alerte\">CIVD</span> ; <span class=\"kw-alerte\">MAT</span> (PTT, SHU)<br><span class=\"kw-clinique\">Syndrome de Kasabach</span>-Merritt</td>\n            <td>Moelle <strong>riche</strong> en mégacaryocytes normaux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Périphérique — destruction</span></td>\n            <td><strong>Destruction</strong> accélérée, le plus souvent <span class=\"kw-def\">immunologique</span></td>\n            <td><span class=\"kw-etio\">PTI</span> ; maladies auto-immunes<br><span class=\"kw-etio\">Infections virales</span> ; <span class=\"kw-ttt\">causes médicamenteuses</span> immuno-allergiques</td>\n            <td>Moelle <strong>riche</strong> en mégacaryocytes normaux</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Un <strong>4ᵉ mécanisme</strong> est à connaître : l'<span class=\"kw-def\">hyperséquestration splénique</span> (hypersplénisme), où <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">plaquettes</span> sont piégées dans une rate volumineuse — thrombopénie alors modérée. La <strong>dilution</strong> (transfusions/perfusions massives) en est un cas particulier.</p>\n      <div class=\"callout callout-info\">📌 Le <span class=\"kw-etio\">PTI</span> illustre l'<strong>intrication</strong> possible des mécanismes : destruction périphérique (phagocytose splénique des <span class=\"kw-bio\">plaquettes</span>) <strong>et</strong> composante centrale (auto-anticorps freinant la mégacaryopoïèse).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 215 — <span class=\"kw-clinique\">Purpura</span></em></p>","frequence":2},{"id":"214-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques associées aux thrombopénies","contenu":"<p>Le retentissement clinique d'une thrombopénie est un <span class=\"kw-clinique\">syndrome hémorragique cutanéo-muqueux</span>, qui apparaît le plus souvent lorsque <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">plaquettes</span> sont <span class=\"kw-alerte\">&lt; 20 G/L</span>. Les saignements se répartissent par <strong>site anatomique</strong>, du plus banal au plus grave.</p>\n      <ul>\n        <li><strong>Saignements cutanés</strong> — <span class=\"kw-clinique\">purpura thrombopénique</span> (extravasation spontanée des globules rouges), pétéchial et/ou ecchymotique, <span class=\"kw-clinique\">hématomes</span> possibles.</li>\n        <li><strong>Saignements muqueux</strong> — <span class=\"kw-clinique\">épistaxis</span> ; <span class=\"kw-clinique\">gingivorragies</span> (spontanées ou au brossage) ; <span class=\"kw-clinique\">bulles hémorragiques intra-buccales</span> et <span class=\"kw-clinique\">purpura</span> du voile du palais ; hémorragies digestives (<span class=\"kw-clinique\">méléna</span>, <span class=\"kw-clinique\">rectorragies</span>, plus rarement <span class=\"kw-clinique\">hématémèse</span>) ; <span class=\"kw-clinique\">méno-métrorragies</span> ; <span class=\"kw-clinique\">hématurie</span>.</li>\n        <li><strong>Saignements viscéraux</strong> — <span class=\"kw-alerte\">hémorragies cérébro-méningées</span>, rares mais redoutables.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-imagerie\">hémorragies au fond d'œil</span> ne sont recherchées qu'en cas de symptômes visuels. Plus rarement, la thrombopénie est révélée par une <strong>manifestation <span class=\"kw-etio\">thrombotique</span></strong> (le plus souvent <em>sans</em> <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span>) : <span class=\"kw-etio\">TIH de type 2</span>, <span class=\"kw-etio\">MAT</span> (PTT, SHU), <span class=\"kw-etio\">SAPL</span>, <span class=\"kw-etio\">CIVD</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-clinique\">Purpura</span></em></p>","frequence":3},{"id":"214-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques d’un purpura thrombopénique","contenu":"<p>Le <span class=\"kw-def\">purpura thrombopénique</span> correspond à l'<strong>extravasation spontanée</strong> des <span class=\"kw-clinique\">globules rouges</span> dans le tissu sous-cutané ou le chorion. Ses caractéristiques sémiologiques sont stéréotypées et constituent un point d'examen discriminant.</p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th><span class=\"kw-clinique\">Purpura</span> thrombopénique</th></tr></thead>\n        <tbody>\n          <tr><td>Aspect</td><td><span class=\"kw-clinique\">Monomorphe</span> — <span class=\"kw-clinique\">pétéchial</span> et/ou <span class=\"kw-clinique\">ecchymotique</span></td></tr>\n          <tr><td>Relief</td><td><span class=\"kw-clinique\">Non infiltré</span> (plan, ne se palpe pas)</td></tr>\n          <tr><td>Topographie</td><td><span class=\"kw-clinique\">Diffus</span>, à <span class=\"kw-clinique\">prédominance cutanée</span> ; <span class=\"kw-clinique\">hématomes</span> possibles</td></tr>\n          <tr><td>Survenue</td><td><span class=\"kw-clinique\">Spontanée</span>, sans facteur déclenchant</td></tr>\n        </tbody>\n      </table>\n      <p>Le caractère <span class=\"kw-clinique\">non infiltré</span> est l'élément discriminant : il oppose le <span class=\"kw-clinique\">purpura</span> thrombopénique au <span class=\"kw-etio\">purpura vasculaire</span>, <span class=\"kw-clinique\">infiltré et palpable</span> (cf. item 215).</p>\n      <div class=\"callout callout-danger\">🚩 Un <span class=\"kw-clinique\">purpura</span> <span class=\"kw-alerte\">ecchymotique extensif, disséminé, voire nécrotique</span> est un <span class=\"kw-alerte\">signe de gravité</span> : il impose une <span class=\"kw-alerte\">évaluation en urgence</span> (cf. <span class=\"kw-alerte\">signes de gravité</span>, obj-6).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-clinique\">Purpura</span></em></p>","frequence":3},{"id":"214-5","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un purpura thrombopénique","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie de <span class=\"kw-clinique\">purpura</span> thrombopénique n'est présente dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>214-thrombopenie/</code>. Kevin enrichira ce paragraphe avec une photo clinique (Pilly, Collège de médecine interne ou recherche web ciblée) + sémiologie commentée : <span class=\"kw-clinique\">purpura pétéchial</span> et/ou ecchymotique, <span class=\"kw-clinique\">non infiltré</span>, monomorphe, diffus à prédominance cutanée (cf. caractéristiques cliniques, obj-3).\n      </div>\n      <!-- TODO Kevin : ajouter une photo clinique + légende -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 215 — <span class=\"kw-clinique\">Purpura</span></em></p>","frequence":0},{"id":"214-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une bulle intrabuccale","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie de <span class=\"kw-clinique\">bulle</span> intrabuccale n'est présente dans <span class=\"kw-clinique\">les</span> fiches sources. Kevin enrichira avec une photo clinique + sémiologie : <span class=\"kw-clinique\">bulle hémorragique de la muqueuse buccale</span> (langue, face interne des joues, palais), signe d'une <span class=\"kw-alerte\">thrombopénie profonde</span> (<span class=\"kw-chiffre\">&lt; 20 G/L</span>) et élément du <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span> muqueux.\n      </div>\n      <!-- TODO Kevin : ajouter une photo clinique + légende -->\n      <p>Sémiologiquement, la <span class=\"kw-clinique\">bulle hémorragique intra-buccale</span> est considérée comme <span class=\"kw-alerte\">pathognomonique</span> d'une <span class=\"kw-alerte\">thrombopénie sévère</span>. Elle est intégrée au <span class=\"kw-def\">score de Buchanan</span> (<span class=\"kw-def\">score</span> <span class=\"kw-etio\">hémorragique</span> pédiatrique du PTI), à la rubrique « Bouche » : bulles sans saignement actif → saignement actif continu selon le grade.</p>","frequence":2},{"id":"214-7","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité et les urgences vitales devant une thrombopénie","contenu":"<p>La thrombopénie expose à un risque d'<span class=\"kw-alerte\">hémorragie spontanée grave</span>, avec une <span class=\"kw-def\">mortalité</span> d'environ <span class=\"kw-chiffre\">5 %</span>. Trois ordres de facteurs conditionnent la gravité.</p>\n      <table >\n        <thead><tr><th>Axe de gravité</th><th>Éléments à reconnaître</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Biologique</span></strong></td>\n            <td>Profondeur : thrombopénie <span class=\"kw-alerte\">&lt; 20 G/L</span> souvent symptomatique<br>Mécanisme : risque <span class=\"kw-etio\">hémorragique</span> plus élevé si origine <span class=\"kw-def\">centrale</span> que périphérique, à chiffre égal</td>\n          </tr>\n          <tr>\n            <td><strong>Contextuel</strong> / <span class=\"kw-def\">terrain</span></td>\n            <td>Âge <span class=\"kw-chiffre\">&gt; 65 ans</span> ; <span class=\"kw-def\">comorbidités</span> hémorragiques<br><span class=\"kw-clinique\">Lésion</span> susceptible de saigner : site opératoire ; <span class=\"kw-etio\">ulcère gastroduodénal</span> ; lésion <span class=\"kw-etio\">tumorale</span><br>Traitements interférant avec l'hémostase : <span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-ttt\">ISRS</span> ; <span class=\"kw-ttt\">anticoagulants</span></td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong> 🚩</td>\n            <td><span class=\"kw-clinique\">Purpura</span> <span class=\"kw-alerte\">ecchymotique extensif/nécrotique</span> ; hématomes spontanés confluents (membres supérieurs, tronc)<br>Saignements muqueux graves : <span class=\"kw-clinique\">bulles hémorragiques intra-buccales</span> ; épistaxis bilatérale ; gingivorragies spontanées ; méno-métrorragies ; <span class=\"kw-bio\">hématurie</span> macroscopique ; hémorragie digestive ; <span class=\"kw-imagerie\">hémorragies au fond d'œil</span><br>Tout saignement avec déglobulisation</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚨 <strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Tout signe neurologique — <span class=\"kw-alerte\">céphalées même isolées</span>, confusion, <span class=\"kw-alerte\">coma</span>, déficit — doit faire craindre une <span class=\"kw-alerte\">hémorragie cérébro-méningée</span> et impose une <span class=\"kw-imagerie\">imagerie cérébrale (TDM) en urgence</span>. Dans le PTI, l'association <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 30 G/L</span> + <span class=\"kw-def\">score</span> <span class=\"kw-etio\">hémorragique</span> élevé (Khellaf <span class=\"kw-chiffre\">≥ 8</span> ou Buchanan &gt; 3) définit l'urgence thérapeutique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":3},{"id":"214-8","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître une fausse thrombopénie","contenu":"<p>Avant toute exploration, il faut éliminer une <span class=\"kw-def\">fausse thrombopénie</span> (« pseudo-thrombopénie »), artéfact pré-analytique le plus souvent lié au tube <span class=\"kw-bio\">EDTA</span>. Le prélèvement de <span class=\"kw-bio\">NFS</span> se fait sur <span class=\"kw-bio\">EDTA</span>, qui peut induire <em>in vitro</em> soit un <strong>amas plaquettaire</strong> (<span class=\"kw-bio\">agrégation des plaquettes</span> entre elles), soit un <strong>satellitisme</strong> (rosette de <span class=\"kw-bio\">plaquettes</span> autour des <span class=\"kw-bio\">polynucléaires</span>). Sa <span class=\"kw-def\">prévalence</span> est d'environ <span class=\"kw-chiffre\">1 patient sur 5 000</span>.</p>\n      <p><strong>Quand la rechercher ?</strong> Devant toute <span class=\"kw-clinique\">thrombopénie sans signe hémorragique cutanéo-muqueux</span>. À l'inverse, elle <strong>ne se recherche pas</strong> en présence d'un <span class=\"kw-clinique\">syndrome hémorragique</span> authentique.</p>\n      <p><strong>Conduite à tenir</strong> : <span class=\"kw-bio\">frottis sanguin</span> à la recherche d'<span class=\"kw-bio\">agrégats</span> ou de <span class=\"kw-bio\">satellitisme</span>, puis nouveau prélèvement sur tube <span class=\"kw-bio\">citraté</span> (le citrate chélate le calcium et empêche l'agrégation) — voire tube <span class=\"kw-bio\">hépariné</span>, tube capillaire ou micro-méthode.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Sur tube <span class=\"kw-bio\">citraté</span>, le résultat plaquettaire est <span class=\"kw-chiffre\">sous-estimé d'environ 10 %</span> par dilution. La simple visualisation d'<span class=\"kw-bio\">agrégats</span> ou de <span class=\"kw-bio\">satellitisme</span> sur le frottis suffit à affirmer la fausse thrombopénie.</div>","frequence":1},{"id":"214-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","contenu":"<p><span class=\"kw-clinique\">Les</span> causes de thrombopénie se classent selon le <strong>mécanisme</strong>. Le tableau ci-dessous retranscrit le tableau étiologique de la fiche source.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Principales étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Centrales</span><br>(défaut de production)</td>\n            <td><span class=\"kw-etio\">Envahissement médullaire</span> ; <span class=\"kw-etio\">myélofibrose</span> ; <span class=\"kw-etio\">myélodysplasie</span><br><span class=\"kw-etio\">Aplasie médullaire</span> (idiopathique, <span class=\"kw-etio\">toxique</span>, médicamenteuse)<br><span class=\"kw-etio\">Mégaloblastoses</span> : carence en vitamine B9 ou B12<br><span class=\"kw-etio\">Alcoolisme chronique</span><br>Thrombopénies <span class=\"kw-etio\">constitutionnelles</span> : Wiskott-Aldrich ; syndromes MYH9 (May-Hegglin) ; amégacaryocytoses congénitales</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Périphériques — consommation</span></td>\n            <td><span class=\"kw-alerte\">CIVD</span><br><span class=\"kw-alerte\">MAT</span> : <span class=\"kw-clinique\">purpura</span> <span class=\"kw-etio\">thrombotique</span> thrombocytopénique (PTT) ; syndrome hémolytique et urémique (SHU)<br>Autres : prothèse valvulaire ; CEC ; <span class=\"kw-clinique\">syndrome de Kasabach</span>-Merritt</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Périphériques — destruction</span></td>\n            <td><span class=\"kw-etio\">PTI</span> (diagnostic d'élimination)<br>Maladies auto-immunes : <span class=\"kw-etio\">lupus</span> ; <span class=\"kw-etio\">SAPL</span> ; syndrome d'Evans (AHAI + PTI)<br>Hémopathies : <span class=\"kw-etio\">LLC</span> ; déficits immunitaires (DICV)<br>Infections virales : <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">VHC</span> &gt; <span class=\"kw-etio\">VHB</span> ; EBV ; CMV ; parvovirus B19<br>Mécanismes multiples : <span class=\"kw-etio\">paludisme</span> ; dengue ; <span class=\"kw-alerte\">sepsis</span><br>Immuno-<span class=\"kw-etio\">allergique</span> médicamenteux : <span class=\"kw-alerte\">TIH</span> (<span class=\"kw-ttt\">héparine</span>) ; <span class=\"kw-ttt\">quinine</span> ; <span class=\"kw-ttt\">thiazidiques</span> ; <span class=\"kw-ttt\">AINS</span> ; antibiotiques (<span class=\"kw-ttt\">cotrimoxazole</span>, <span class=\"kw-ttt\">rifampicine</span>, β-lactamines)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hyperséquestration / dilution</span></td>\n            <td><span class=\"kw-etio\">Hypersplénisme</span> : séquestration plaquettaire splénique<br>Dilution par transfusions ou perfusions massives</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"kw-def\">terrain</span></strong> oriente fortement : chez l'<strong>enfant</strong>, le <span class=\"kw-etio\">PTI</span> aigu post-<span class=\"kw-etio\">viral</span> et le <span class=\"kw-etio\">SHU typique</span> (post-diarrhéique) dominent, de même que <span class=\"kw-clinique\">les</span> thrombopénies constitutionnelles ; chez l'<strong>adulte</strong>, on évoque davantage les causes <span class=\"kw-ttt\">médicamenteuses</span>, l'<span class=\"kw-etio\">alcoolisme</span> et les <span class=\"kw-etio\">hémopathies</span> (syndrome myélodysplasique après <span class=\"kw-chiffre\">50 ans</span>).</p>\n      <div class=\"callout callout-info\">📌 En soins critiques, retenir aussi : <span class=\"kw-alerte\">thrombopénie septique</span> ; <span class=\"kw-alerte\">CAPS</span> (SAPL catastrophique) ; <span class=\"kw-alerte\">syndrome d'activation macrophagique</span> ; allo-immunisation anti-plaquettaire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 169 — Infections à <span class=\"kw-etio\">VIH</span> · 194 — <span class=\"kw-clinique\">Lupus</span> - SAPL · 275 — <span class=\"kw-clinique\">Splénomégalie</span> · 279 — Cirrhose · 315 — Leucémie aiguë</em></p>","frequence":2},{"id":"214-10","rang":"A","rubrique":"Étiologies","titre":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","contenu":"<p>La démarche est <strong>algorithmique</strong> : elle rattache la thrombopénie à un mécanisme puis à une cause. Elle s'organise en étapes successives (retranscription de l'algorithme source).</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Examen / action</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Éliminer une fausse thrombopénie</strong></td><td><span class=\"kw-bio\">Frottis sanguin</span> ; au besoin contrôle sur tube citraté</td><td>Agrégats / satellitisme → pseudo-thrombopénie (cf. obj-7)</td></tr>\n          <tr><td><strong>2. Identifier une <span class=\"kw-alerte\">urgence</span></strong></td><td>Recherche d'un <span class=\"kw-clinique\">syndrome hémorragique</span> grave et de signes neurologiques</td><td><span class=\"kw-alerte\">Signes de gravité</span> → PEC sans attendre l'étiologie (cf. obj-6)</td></tr>\n          <tr><td><strong>3. Analyser l'hémogramme</strong></td><td><span class=\"kw-bio\">NFS</span> complète : thrombopénie isolée <em>ou</em> autres cytopénies associées ?</td><td>Cytopénies associées, blastes, monocytose → suspicion d'origine <span class=\"kw-def\">centrale</span></td></tr>\n          <tr><td><strong>4. Lire le frottis</strong></td><td><span class=\"kw-bio\">Frottis cytologique</span> : <span class=\"kw-bio\">schizocytes</span> ; cellules anormales ; syndrome mononucléosique</td><td>Schizocytes → <span class=\"kw-alerte\">MAT</span> (<span class=\"kw-alerte\">urgence</span>) ; cellules anormales → hémopathie</td></tr>\n          <tr><td><strong>5. Bilan d'hémostase</strong></td><td><span class=\"kw-bio\">TP, TCA, fibrinogène</span> ; <span class=\"kw-bio\">D-dimères</span></td><td>Coagulopathie de consommation → <span class=\"kw-alerte\">CIVD</span></td></tr>\n          <tr><td><strong>6. Bilan orienté</strong></td><td><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH/VHC/VHB</span> systématiques ; <span class=\"kw-imagerie\">échographie abdominale</span> ; <span class=\"kw-bio\">AAN</span> ; selon contexte <span class=\"kw-imagerie\">myélogramme</span> ou <span class=\"kw-bio\">MAIPA</span></td><td><span class=\"kw-clinique\">Splénomégalie</span>, MAI, infection… ou diagnostic d'exclusion = <span class=\"kw-etio\">PTI</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'<strong>interrogatoire et l'examen clinique</strong> conditionnent l'orientation. Quelques associations à connaître :</p>\n      <ul>\n        <li><strong>Femme jeune</strong> : <span class=\"kw-etio\">lupus systémique</span> ; <span class=\"kw-clinique\">syndrome de Gougerot</span>-<span class=\"kw-clinique\">Sjögren</span>.</li>\n        <li><strong>Thromboses / antécédents obstétricaux</strong> : <span class=\"kw-etio\">SAPL</span>.</li>\n        <li><strong>Infections récidivantes</strong> : <span class=\"kw-etio\">déficits immunitaires</span>.</li>\n        <li><strong>Adulte &gt;<span class=\"kw-chiffre\"> 50 ans</span>, anémie ou leucopénie associée</strong> : <span class=\"kw-etio\">hémopathies</span> (syndromes myélodysplasiques +++).</li>\n        <li><strong><span class=\"kw-clinique\">Splénomégalie</span></strong> : hépatopathie avec <span class=\"kw-clinique\">hypertension</span> portale ; hémopathie lymphoïde.</li>\n        <li><strong>Contexte fébrile</strong> : <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">virale</span> (<span class=\"kw-etio\">EBV</span>, CMV, VIH).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Démarche en soins critiques.</strong> Devant une thrombopénie aiguë : bilan de coagulation anormal → <span class=\"kw-alerte\">CIVD</span> ; sinon anémie hémolytique + <span class=\"kw-bio\">LDH</span> élevés + dysfonction d'organe → <span class=\"kw-alerte\">MAT</span> ; sinon rechercher TIH, cause médicamenteuse, hypersplénisme, hémopathie. En l'absence d'orientation, le <span class=\"kw-imagerie\">myélogramme</span> doit être réalisé rapidement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 215 — <span class=\"kw-clinique\">Purpura</span> · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":6},{"id":"214-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications du myélogramme devant une thrombopénie","contenu":"<p>Le <span class=\"kw-imagerie\">myélogramme</span> n'est <strong>pas systématique</strong> devant une thrombopénie. Il distingue origine centrale (mégacaryocytes absents/dysmorphiques, cellules anormales) et périphérique (<strong>moelle riche en mégacaryocytes normaux</strong>) — un myélogramme normal n'exclut cependant ni l'une ni l'autre.</p>\n      <table >\n        <thead><tr><th>Indication du myélogramme</th><th>Précisions adulte / enfant</th></tr></thead>\n        <tbody>\n          <tr><td>Cytopénie(s) associée(s)</td><td>Anomalie d'une autre lignée sur l'hémogramme ou le frottis (monocytose, macrocytose, cellules anormales) — bi/pancytopénie</td></tr>\n          <tr><td>Syndrome <span class=\"kw-etio\">tumoral</span></td><td><span class=\"kw-clinique\">Adénopathie</span> ; <span class=\"kw-clinique\">splénomégalie</span> ; <span class=\"kw-clinique\">hépatomégalie</span><br>Chez l'enfant : douleurs osseuses ; <span class=\"kw-clinique\">AEG</span></td></tr>\n          <tr><td>Selon le <span class=\"kw-def\">terrain</span></td><td><strong>Adulte &gt;<span class=\"kw-chiffre\"> 60 ans</span></strong> : recherche d'un SMD — myélogramme + caryotype ± FISH<br><strong>Enfant</strong> : signes de maladie de Fanconi (petite taille, anomalie des pouces, dysmorphie)</td></tr>\n          <tr><td>PTI réfractaire</td><td>Échec des traitements usuels (<span class=\"kw-ttt\">corticoïdes</span>, IgIV), notamment avant une splénectomie</td></tr>\n        </tbody>\n      </table>\n      <p>À l'inverse, le myélogramme <strong>n'est pas indiqué</strong> dans un <span class=\"kw-etio\">PTI typique</span> : thrombopénie <em>isolée</em>, sans cytopénie associée, frottis normal, examen clinique normal. La <span class=\"kw-imagerie\">biopsie ostéo-médullaire (BOM)</span> complète le myélogramme lorsqu'il est non contributif et qu'on suspecte une <span class=\"kw-etio\">aplasie</span> ou une <span class=\"kw-etio\">myélofibrose</span> (numération <span class=\"kw-chiffre\">&gt; 50 G/L</span> requise, sinon transfusion préalable).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 316 — Syndrome myélodysplasique</em></p>","frequence":1},{"id":"214-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à prescrire devant une thrombopénie de l’enfant et de l’adulte","contenu":"<p>Le bilan paraclinique d'une thrombopénie comporte un <strong>socle systématique</strong> et des examens <strong>orientés</strong> par le contexte. Certains examens sont explicitement inutiles et ne doivent pas être prescrits.</p>\n      <table >\n        <thead><tr><th>Niveau de bilan</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan systématique</span></td>\n            <td><span class=\"kw-bio\">NFS + frottis sanguin</span> (sur tube citraté si doute sur une fausse thrombopénie)<br>Créatinine ; <span class=\"kw-bio\">bandelette urinaire</span><br>Bilan hépatique : <span class=\"kw-bio\">ASAT</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">PAL</span>, <span class=\"kw-bio\">GGT</span>, <span class=\"kw-bio\">bilirubine</span><br><span class=\"kw-bio\">Électrophorèse des protéines</span> ou dosage pondéral des Ig<br>Bilan de coagulation : <span class=\"kw-bio\">TP, TCA, fibrinogène</span><br><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH, VHB, VHC</span><br><span class=\"kw-bio\">Anticorps anti-nucléaires</span> (AAN) ; groupe sanguin + RAI dans <span class=\"kw-clinique\">les</span> formes sévères</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan orienté</span><br>(selon le contexte)</td>\n            <td><span class=\"kw-imagerie\">Myélogramme</span> ± caryotype/FISH<br>Recherche de SAPL ; <span class=\"kw-bio\">bilan thyroïdien</span> (<span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">anti-TPO</span>)<br>Recherche d'<span class=\"kw-etio\">Helicobacter pylori</span> chez l'adulte (breath-test ou Ag dans <span class=\"kw-clinique\">les</span> selles)<br><span class=\"kw-imagerie\">Échographie</span> abdominale ; immunophénotypage lymphocytaire<br><span class=\"kw-bio\">Anticorps anti-plaquettes (MAIPA)</span> ; durée de vie isotopique des <span class=\"kw-bio\">plaquettes</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">Examens inutiles</span></td>\n            <td>Temps de saignement ; dosage du <span class=\"kw-bio\">complément</span> ; dosage de la thrombopoïétine ; recherche de <span class=\"kw-bio\">plaquettes</span> réticulées</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <strong><span class=\"kw-bio\">différenciation</span> enfant / adulte</strong> est importante : chez l'enfant, un <span class=\"kw-etio\">PTI</span> typique post-<span class=\"kw-etio\">viral</span> ne nécessite qu'un bilan minimal ; chez l'adulte, le bilan étendu (<span class=\"kw-bio\">sérologies</span>, AAN, <span class=\"kw-etio\">H. pylori</span>) est requis pour ne pas méconnaître une cause secondaire.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 169 — Infections à <span class=\"kw-etio\">VIH</span> · 194 — <span class=\"kw-clinique\">Lupus</span> - SAPL · 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span></em></p>","frequence":2},{"id":"214-13","rang":"B","rubrique":"Contenu multimédia","titre":"Fond d’œil","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune iconographie de <span class=\"kw-imagerie\">fond d'œil</span> n'est présente dans <span class=\"kw-clinique\">les</span> fiches sources. Kevin enrichira avec une photo de <span class=\"kw-imagerie\">FO</span> + sémiologie : <span class=\"kw-imagerie\">hémorragies rétiniennes</span> évocatrices d'une <span class=\"kw-alerte\">thrombopénie profonde</span> avec risque <span class=\"kw-etio\">hémorragique</span> sévère. Le <span class=\"kw-imagerie\">fond d'œil</span> n'est réalisé qu'en présence de <span class=\"kw-clinique\">symptômes visuels</span> ; les hémorragies rétiniennes figurent parmi les <span class=\"kw-alerte\">signes de gravité</span> (cf. obj-6). À l'inverse, le <span class=\"kw-imagerie\">FO</span> est <span class=\"kw-ci\">inutile dans le PTI</span> (mauvaise VPN).\n      </div>\n      <!-- TODO Kevin : ajouter une photo de FO + légende -->","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> vitale <span class=\"kw-etio\">hémorragique</span></strong></p><p><span class=\"kw-imagerie\">TDM cérébrale</span> sans délai · identifier le <span class=\"kw-def\">mécanisme</span> conditionne le traitement</p><ul><li><span class=\"kw-def\">Mortalité</span> de l'hémorragie spontanée ≈ <span class=\"kw-chiffre\">5 %</span></li><li>PTI : <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-alerte\">&lt; 30 G/L</span> + <span class=\"kw-def\">score de Khellaf ≥ 8</span> ou <span class=\"kw-def\">Buchanan &gt; 3</span></li><li>Tout <span class=\"kw-alerte\">signe neurologique</span> (<span class=\"kw-clinique\">céphalée même isolée</span>, confusion, <span class=\"kw-alerte\">coma</span>, déficit) → <span class=\"kw-alerte\">hémorragie cérébro-méningée</span></li></ul><p><strong>Seuils transfusionnels plaquettaires <span class=\"q\">— prophylactiques</span></strong></p><p><span class=\"kw-ci\">Transfusion plaquettaire contre-indiquée dans les MAT</span> (PTT/SHU — elle aggrave la microthrombose) ; dans la <span class=\"kw-alerte\">CIVD</span> elle reste indiquée si <span class=\"kw-alerte\">hémorragie active</span></p><ul><li><span class=\"kw-chiffre\">&lt; 10 G/L</span> : <span class=\"kw-ttt\">transfusion systématique</span> (sauf MAT)</li><li><span class=\"kw-chiffre\">&lt; 50 G/L</span> : avant <span class=\"kw-ttt\">chirurgie</span> mineure, PL, ponction pleurale, <span class=\"kw-imagerie\">BOM</span></li><li><span class=\"kw-chiffre\">&lt; 80 G/L</span> : <span class=\"kw-ttt\">chirurgie</span> majeure · <span class=\"kw-chiffre\">&lt; 100 G/L</span> : <span class=\"kw-ttt\">neurochirurgie</span> / chirurgie oculaire</li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Purpura</span> <span class=\"kw-alerte\">ecchymotique extensif, disséminé voire nécrotique</span></li><li><span class=\"kw-alerte\">Hématomes spontanés et confluents</span> (membres supérieurs, tronc)</li><li>Saignements muqueux graves : <span class=\"kw-clinique\">bulles hémorragiques intra-buccales</span>, épistaxis bilatérale, gingivorragies spontanées, méno-métrorragies, <span class=\"kw-bio\">hématurie</span> macroscopique, hémorragie digestive</li><li><span class=\"kw-imagerie\">Hémorragies au fond d'œil</span></li><li><span class=\"kw-alerte\">Signe neurologique</span> (<span class=\"kw-clinique\">céphalée</span> même isolée, confusion, <span class=\"kw-alerte\">coma</span>, déficit) → <span class=\"kw-alerte\">hémorragie cérébro-méningée</span></li><li>Tout <span class=\"kw-alerte\">saignement avec déglobulisation</span></li><li>Profondeur <span class=\"kw-alerte\">&lt; 20 G/L</span> ou mécanisme <span class=\"kw-def\">central</span> (risque <span class=\"kw-etio\">hémorragique</span> majoré à chiffre égal) ; <span class=\"kw-def\">terrain</span> : <span class=\"kw-chiffre\">âge &gt; 65 ans</span>, <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">ISRS</span> / <span class=\"kw-ttt\">anticoagulants</span></li></ul>","principes":"<p>Le traitement est <strong>étiologique</strong> : il dépend du <span class=\"kw-def\">mécanisme</span>, identifié avant de traiter. Règle transversale = <span class=\"kw-ci\">éviter les traitements altérant l'hémostase</span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-ttt\">anticoagulants</span>) et <span class=\"kw-ci\">encadrer les gestes à risque</span> (<span class=\"kw-ci\">injection IM</span>, ponctions, <span class=\"kw-ttt\">avulsion</span> dentaire).</p><p><strong>Thrombopénie centrale</strong></p><ul><li>Traitement de la <span class=\"kw-etio\">cause</span> + <span class=\"kw-ttt\">transfusion plaquettaire</span> (efficace ici)</li></ul><p><strong><span class=\"kw-alerte\">CIVD</span></strong></p><ul><li>Traitement de la <span class=\"kw-etio\">cause</span> (souvent <span class=\"kw-alerte\">sepsis</span>)</li><li><span class=\"kw-ttt\">Transfusion CP + fibrinogène + PFC</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span></li></ul><p><strong>MAT <span class=\"q\">— PTT / SHU</span></strong></p><p><span class=\"kw-ci\">Transfusion plaquettaire contre-indiquée</span> (aggrave la MAT)</p><ul><li>PTT : <span class=\"kw-ttt\">échanges plasmatiques + PFC</span> ± <span class=\"kw-ttt\">rituximab</span></li><li>SHU typique : <span class=\"kw-ttt\">symptomatique</span> (favorable en <span class=\"kw-chiffre\">1–2 semaines</span>) ; SHU atypique : <span class=\"kw-ttt\">anti-C5 du complément</span></li></ul><p><strong>PTI</strong></p><p><span class=\"kw-alerte\">Urgence</span> : <span class=\"kw-ttt\">corticoïdes IV forte dose + Ig IV</span> ; <span class=\"kw-ci\">transfusion plaquettaire non indiquée</span> sauf hémorragie neuro/digestive grave</p><ul><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">≥ 30 G/L</span> asymptomatique : <span class=\"kw-ttt\">abstention + surveillance</span></li><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">&lt; 30 G/L</span> ou Buchanan &gt; 3 : <span class=\"kw-ttt\">corticoïdes</span> (<span class=\"kw-ttt\">prednisone</span> <span class=\"kw-chiffre\">1 mg/kg/j</span>) ± <span class=\"kw-ttt\">IgIV</span> (si <span class=\"kw-def\">score</span> &gt; 8)</li><li>2ᵉ ligne : <span class=\"kw-ttt\">splénectomie</span>, <span class=\"kw-ttt\">agonistes du récepteur de la TPO</span>, <span class=\"kw-ttt\">rituximab</span>, <span class=\"kw-ttt\">dapsone</span></li></ul><p><strong>Hypersplénisme</strong></p><ul><li>Thrombopénie modérée : habituellement <span class=\"kw-ttt\">pas de traitement</span> spécifique</li></ul>","suivi":"<p><strong>Sévérité :</strong> appréciée par le <span class=\"kw-def\">score de Khellaf</span> (adulte) ou de <span class=\"kw-def\">Buchanan</span> (enfant), répété ; <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">NFS</span>.<br><strong>PTI :</strong> <span class=\"kw-def\">nouvellement diagnostiqué &lt; 3 mois</span> · <span class=\"kw-def\">persistant 3–12 mois</span> · <span class=\"kw-def\">chronique &gt; 12 mois</span> ; le traitement de fond vise des <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&gt; 30 G/L</span> durables.<br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> enfant = forme aiguë (guérison ≈ <span class=\"kw-chiffre\">80 %</span>) ; adulte = forme chronique (≈ <span class=\"kw-chiffre\">60 %</span>) — attendre ≈ <span class=\"kw-chiffre\">1 an</span> avant la <span class=\"kw-ttt\">splénectomie</span>.<br><strong>Inutile :</strong> <span class=\"kw-ci\">fond d'œil dans le PTI</span> (mauvaise VPN).</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/63.%20Thrombop%C3%A9nie%20en%20soins%20critiques.pdf","label":"CeMIR — 63. thrombopénie en soins critiques"},{"href":"https://radiopaedia.org/articles/immune-thrombocytopenia","label":"Radiopaedia : Immune thrombocytopenia"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Thrombopénie confirmée — fausse thrombopénie éliminée — Mécanisme ? Hémogramme + frottis = 1er tri","detail":"<h4>CAT — démarche étiologique devant une thrombopénie — Fausse thrombopénie éliminée → identifier le mécanisme</h4>","branches":[{"to":"t-central","label":"Cytopénie(s) associée(s) · blastes / cellules anormales","color":"red"},{"to":"q-frottis","label":"Thrombopénie isolée (autres lignées normales)","color":"blue"}]},{"id":"t-central","kind":"terminal","label":"Origine centrale (atteinte médullaire)","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">Myélogramme</span> : mégacaryocytes <span class=\"kw-bio\">absents ou dysmorphiques</span>, cellules anormales (moelle pauvre / envahie)</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Envahissement médullaire</span>, <span class=\"kw-etio\">myélodysplasie</span>, <span class=\"kw-etio\">myélofibrose</span></li><li><span class=\"kw-etio\">Aplasie médullaire</span> (<span class=\"kw-etio\">toxique</span>, médicamenteuse, idiopathique)</li><li><span class=\"kw-etio\">Carence en B9 / B12</span> (mégaloblastose) ; <span class=\"kw-etio\">alcoolisme chronique</span></li><li>Thrombopénies <span class=\"kw-etio\">constitutionnelles</span> (enfant : MYH9 / May-Hegglin, Wiskott-Aldrich)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Transfusion plaquettaire</span> efficace + traitement de la <span class=\"kw-etio\">cause</span></li></ul><h4>Renvoi</h4><ul><li>Item 315 (leucémie aiguë) · Item 316 (syndrome myélodysplasique)</li></ul>"},{"id":"q-frottis","kind":"decision","label":"Frottis : schizocytes / hémolyse mécanique ? — Schizocytes · anémie hémolytique · LDH ↑ · dysfonction d'organe","branches":[{"to":"t-mat","label":"Schizocytes présents","color":"red"},{"to":"q-hemostase","label":"Pas de schizocytes","color":"blue"}]},{"id":"t-mat","kind":"terminal","label":"Microangiopathie thrombotique (PTT / SHU)","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Schizocytes</span> au frottis + <span class=\"kw-clinique\">anémie hémolytique</span> (<span class=\"kw-bio\">LDH ↑</span>, <span class=\"kw-bio\">haptoglobine ↓</span>) + <span class=\"kw-clinique\">dysfonction d'organe</span></li></ul><h4>Conduite</h4><ul><li>PTT : <span class=\"kw-ttt\">échanges plasmatiques + PFC</span> ± <span class=\"kw-ttt\">rituximab</span> — <span class=\"kw-alerte\">urgence</span></li><li>SHU typique : <span class=\"kw-ttt\">symptomatique</span> (favorable en <span class=\"kw-chiffre\">1–2 semaines</span>) ; SHU atypique : <span class=\"kw-ttt\">anti-C5 du complément</span></li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">Transfusion plaquettaire contre-indiquée</span> (aggrave la MAT)</li></ul><h4>Renvoi</h4><ul><li>Item 215 (<span class=\"kw-clinique\">purpura</span> — MAT)</li></ul>"},{"id":"q-hemostase","kind":"decision","label":"Bilan d'hémostase anormal ? — TP, TCA, fibrinogène, D-dimères","branches":[{"to":"t-civd","label":"Anormal (TP ↓ · fibrinogène ↓ · D-dimères ↑)","color":"red"},{"to":"q-oriente","label":"Normal","color":"blue"}]},{"id":"t-civd","kind":"terminal","label":"CIVD (coagulopathie de consommation)","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">TP ↓</span>, <span class=\"kw-bio\">TCA ↑</span>, <span class=\"kw-bio\">fibrinogène ↓</span>, <span class=\"kw-bio\">D-dimères ↑</span></li></ul><h4>Conduite</h4><ul><li>Traitement de la <span class=\"kw-etio\">cause</span> (souvent <span class=\"kw-alerte\">sepsis</span>) + <span class=\"kw-ttt\">CP + fibrinogène + PFC</span> si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 50 G/L</span></li></ul><h4>Renvoi</h4><ul><li>Item 158 (<span class=\"kw-alerte\">sepsis</span> et <span class=\"kw-alerte\">choc septique</span>)</li></ul>"},{"id":"q-oriente","kind":"decision","label":"Orientation étiologique au bilan ? — Médicament (héparine → TIH), virose, MAI, splénomégalie…","branches":[{"to":"t-secondaire","label":"Cause secondaire identifiée","color":"amber"},{"to":"t-pti","label":"Bilan négatif · examen normal","color":"blue"}]},{"id":"t-secondaire","kind":"terminal","label":"Thrombopénie périphérique secondaire","color":"amber","detail":"<h4>Étiologies</h4><ul><li>Immuno-<span class=\"kw-etio\">allergique</span> : <span class=\"kw-alerte\">TIH</span> (<span class=\"kw-ttt\">héparine</span>), <span class=\"kw-ttt\">quinine</span>, <span class=\"kw-ttt\">thiazidiques</span>, <span class=\"kw-ttt\">AINS</span>, antibiotiques</li><li>Infections virales : <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">EBV</span>, CMV, parvovirus B19</li><li>Maladies auto-immunes : <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">SAPL</span>, syndrome d'Evans</li><li><span class=\"kw-etio\">Hypersplénisme</span> (<span class=\"kw-clinique\">splénomégalie</span>) ; <span class=\"kw-etio\">hémopathie</span> (LLC)</li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH / VHB / VHC</span>, <span class=\"kw-bio\">AAN</span>, <span class=\"kw-imagerie\">échographie abdominale</span>, recherche d'<span class=\"kw-etio\">H. pylori</span> chez l'adulte</li></ul><h4>Conduite</h4><ul><li>Traiter la <span class=\"kw-etio\">cause</span> · arrêt du <span class=\"kw-ttt\">médicament</span> imputable</li></ul><h4>Renvoi</h4><ul><li>Item 169 (<span class=\"kw-etio\">VIH</span>) · Item 194 (<span class=\"kw-clinique\">lupus</span> - SAPL) · Item 275 (<span class=\"kw-clinique\">splénomégalie</span>)</li></ul>"},{"id":"t-pti","kind":"terminal","label":"PTI — diagnostic d'élimination","color":"blue","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-def\">Thrombopénie isolée</span>, hémostase normale, examen clinique normal (pas de <span class=\"kw-clinique\">splénomégalie</span>) ; <span class=\"kw-imagerie\">myélogramme</span> non systématique (moelle riche en mégacaryocytes)</li></ul><h4>Myélogramme si</h4><ul><li>Cytopénie associée · syndrome <span class=\"kw-etio\">tumoral</span> · âge <span class=\"kw-chiffre\">&gt; 60 ans</span> (SMD) · PTI réfractaire</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">≥ 30 G/L</span> asymptomatique : <span class=\"kw-ttt\">abstention + surveillance</span></li><li><span class=\"kw-bio\">Plaquettes</span> <span class=\"kw-chiffre\">&lt; 30 G/L</span> ou Buchanan &gt; 3 : <span class=\"kw-ttt\">corticoïdes</span> ± <span class=\"kw-ttt\">IgIV</span> ; 2ᵉ ligne : <span class=\"kw-ttt\">splénectomie</span>, <span class=\"kw-ttt\">agonistes TPO-r</span>, <span class=\"kw-ttt\">rituximab</span></li></ul>"}]},"cards":[{"i":"2dbc06d112dd","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"Existe-t-il une corrélation stricte entre la numération plaquettaire et l'importance des signes cliniques dans la thrombopénie ?","a":"<p>Non, l'importance des signes cliniques n'est <strong>pas strictement corrélée</strong> à la numération plaquettaire, bien que la profondeur de la thrombopénie oriente le risque hémorragique.</p>"},{"i":"a4ae512a98c1","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"Quel est le risque hémorragique pour une numération plaquettaire comprise entre 20 et 50 G/L ?","a":"<p>Pour une numération plaquettaire comprise entre <strong>20 et 50 G/L</strong>, les signes hémorragiques sont <strong>rares</strong>, sauf en présence d'un facteur surajouté.</p>"},{"i":"b1f28a4cad79","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"Comment définit-on une thrombopénie chez l'adulte et l'enfant ?","a":"<p>Une thrombopénie se définit par un nombre de plaquettes circulantes <strong>inférieur à 150 G/L</strong>, quel que soit l'âge.</p>"},{"i":"b5c91b1b375d","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"Quel est le risque hémorragique spontané pour une numération plaquettaire supérieure à 50 G/L ?","a":"<p>Pour une numération plaquettaire <strong>supérieure à 50 G/L</strong>, les saignements spontanés sont <strong>exceptionnels</strong> et le patient est le plus souvent asymptomatique, sauf en cas de thrombopathie associée (ex: insuffisance rénale, certains médicaments).</p>"},{"i":"cba4873b36ad","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"Quel seuil de plaquettes circulantes est parfois considéré comme physiologique chez certaines populations ?","a":"<p>Un seuil entre <strong>100 et 150 G/L</strong> peut être physiologique dans certaines populations, notamment les sujets d'origine <strong>orientale ou africaine</strong>.</p>"},{"i":"e7c36dcbd3e9","n":214,"o":"214-1","u":"Définition","t":"Connaître la définition d’une thrombopénie","q":"À partir de quel seuil de numération plaquettaire une thrombopénie est-elle souvent symptomatique avec un syndrome hémorragique fréquent ?","a":"<p>Une thrombopénie est souvent symptomatique avec un syndrome hémorragique fréquent lorsque la numération plaquettaire est <strong>inférieure à 20 G/L</strong>.</p>"},{"i":"0241c901110a","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Quelle cause de thrombopénie doit être évoquée chez une femme jeune présentant des thromboses ou des antécédents obstétricaux ?","a":"<p>Chez une femme jeune présentant une thrombopénie associée à des événements thrombotiques ou des antécédents obstétricaux (fausses couches à répétition, pré-éclampsie), le <strong>syndrome des antiphospholipides (SAPL)</strong> doit être évoqué.</p>"},{"i":"30cba3cd00cb","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Quels éléments clés rechercher sur le frottis sanguin pour orienter le diagnostic étiologique d'une thrombopénie ?","a":"<p>Le frottis sanguin doit être analysé pour rechercher :</p><ul><li>Des <strong>schizocytes</strong> : ils orientent vers une <strong>microangiopathie thrombotique (MAT)</strong>, qui est une urgence.</li><li>Des <strong>cellules anormales</strong> : elles sont fortement évocatrices d'une <strong>hémopathie</strong>.</li><li>Un <strong>syndrome mononucléosique</strong> : il peut suggérer une cause infectieuse virale.</li></ul>"},{"i":"3d7fed0bd774","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Devant une thrombopénie aiguë sans orientation claire après les premières étapes diagnostiques, quel examen complémentaire doit être réalisé rapidement ?","a":"<p>En l'absence d'orientation diagnostique évidente après les étapes initiales (élimination de fausse thrombopénie, recherche d'urgence, hémogramme, frottis, bilan d'hémostase), la réalisation d'un <strong>myélogramme</strong> est recommandée pour rechercher une cause médullaire.</p>"},{"i":"7761923a6051","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Après avoir éliminé une fausse thrombopénie, quelle doit être l'étape suivante dans la démarche diagnostique ?","a":"<p>Il faut ensuite <strong>identifier une urgence vitale</strong> en recherchant activement un <strong>syndrome hémorragique grave</strong> et/ou des <strong>signes neurologiques</strong>. La présence de ces signes de gravité impose une prise en charge thérapeutique immédiate, avant même l'identification de l'étiologie.</p>"},{"i":"93a37bb2f988","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Quel rôle joue l'hémogramme complet (NFS) dans la démarche diagnostique étiologique d'une thrombopénie ?","a":"<p>L'hémogramme complet permet de déterminer si la <strong>thrombopénie est isolée</strong> ou si elle est <strong>associée à d'autres cytopénies</strong> (anémie, leucopénie). La présence de cytopénies associées, de blastes ou d'une monocytose doit faire suspecter une <strong>origine centrale</strong>, notamment une <strong>hémopathie</strong>.</p>"},{"i":"9d7439865fed","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Quand faut-il suspecter une hémopathie en présence d'une thrombopénie chez l'adulte ?","a":"<p>Une hémopathie, notamment un <strong>syndrome myélodysplasique</strong>, doit être fortement suspectée chez un <strong>adulte de plus de 50 ans</strong> si la thrombopénie est associée à une <strong>anémie ou une leucopénie</strong>.</p>"},{"i":"c89809644124","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Quelle est la première étape de la démarche diagnostique devant une thrombopénie chez l'adulte et l'enfant ?","a":"<p>La première étape est d'<strong>éliminer une fausse thrombopénie</strong> ou <strong>pseudo-thrombopénie</strong>. Cela se fait par la réalisation d'un frottis sanguin et, si nécessaire, d'un contrôle sur tube citraté, afin de rechercher des agrégats plaquettaires ou un satellitisme des plaquettes autour des polynucléaires.</p>"},{"i":"e9d1ec1141a1","n":214,"o":"214-10","u":"Étiologies","t":"Connaître la démarche diagnostique étiologique devant une thrombopénie de l’enfant et de l’adulte","q":"Dans quel cas le bilan d'hémostase est-il particulièrement utile face à une thrombopénie ?","a":"<p>Le bilan d'hémostase, comprenant le TP, le TCA, le fibrinogène et les D-dimères, est particulièrement utile pour diagnostiquer une <strong>coagulopathie de consommation</strong>, qui est le mécanisme physiopathologique de la <strong>CIVD (Coagulation IntraVasculaire Disséminée)</strong>.</p>"},{"i":"20876b1ffa02","n":214,"o":"214-12","u":"Examens complémentaires","t":"Connaître les examens à prescrire devant une thrombopénie de l’enfant et de l’adulte","q":"Quels sont les examens complémentaires jugés inutiles et ne devant pas être prescrits devant une thrombopénie ?","a":"<p>Les examens jugés inutiles devant une thrombopénie sont :</p><ul><li>Le <strong>temps de saignement</strong>.</li><li>Le dosage du <strong>complément</strong>.</li><li>Le dosage de la <strong>thrombopoïétine</strong>.</li><li>La recherche de <strong>plaquettes réticulées</strong>.</li></ul>"},{"i":"9f9ca21a6900","n":214,"o":"214-12","u":"Examens complémentaires","t":"Connaître les examens à prescrire devant une thrombopénie de l’enfant et de l’adulte","q":"Quel est le bilan systématique à réaliser devant une thrombopénie chez l'adulte et l'enfant ?","a":"<p>Le bilan systématique devant une thrombopénie comprend :</p><ul><li>Une <strong>NFS avec frottis sanguin</strong> (sur tube citraté si doute sur une fausse thrombopénie).</li><li><strong>Créatininémie</strong> et <strong>bandelette urinaire</strong>.</li><li>Un <strong>bilan hépatique</strong> (ASAT, ALAT, PAL, GGT, bilirubine).</li><li>Une <strong>électrophorèse des protéines</strong> ou un dosage pondéral des immunoglobulines.</li><li>Un <strong>bilan de coagulation</strong> (TP, TCA, fibrinogène).</li><li>Des <strong>sérologies VIH, VHB, VHC</strong>.</li><li>La recherche d'<strong>anticorps anti-nucléaires (AAN)</strong>.</li><li>Un <strong>groupe sanguin et RAI</strong> en cas de forme sévère.</li></ul>"},{"i":"f40caed9ea7d","n":214,"o":"214-12","u":"Examens complémentaires","t":"Connaître les examens à prescrire devant une thrombopénie de l’enfant et de l’adulte","q":"Quels examens complémentaires orientés par le contexte peuvent être réalisés face à une thrombopénie chez l'adulte ou l'enfant ?","a":"<p>Selon le contexte clinique, les examens complémentaires orientés peuvent inclure :</p><ul><li>Un <strong>myélogramme</strong> (avec ± caryotype/FISH).</li><li>La recherche de <strong>SAPL</strong> ou un bilan thyroïdien (TSH, anti-TPO).</li><li>La recherche d'<strong><em>Helicobacter pylori</em></strong> chez l'adulte (breath-test ou Ag dans les selles).</li><li>Une <strong>échographie abdominale</strong> ou un immunophénotypage lymphocytaire.</li><li>La recherche d'<strong>anticorps anti-plaquettes</strong> (méthode MAIPA) ou la mesure de la durée de vie isotopique des plaquettes.</li></ul>"},{"i":"080af1a69a7f","n":214,"o":"214-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux thrombopénies","q":"Quelle est la manifestation hémorragique viscérale la plus redoutable en cas de thrombopénie chez l'adulte et l'enfant ?","a":"<p>La manifestation viscérale la plus redoutable est l'<strong>hémorragie cérébro-méningée</strong>, bien que rare.</p>"},{"i":"5199a11adbf3","n":214,"o":"214-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux thrombopénies","q":"À partir de quel seuil plaquettaire observe-t-on le plus souvent des saignements en cas de thrombopénie chez l'adulte et l'enfant ?","a":"<p>Les saignements apparaissent le plus souvent lorsque le taux de plaquettes est <strong>inférieur à 20 G/L</strong>.</p>"},{"i":"63c6acd36bbf","n":214,"o":"214-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux thrombopénies","q":"Quel est le type de syndrome hémorragique en cas de thrombopénie chez l'adulte et l'enfant ?","a":"<p>Le retentissement clinique d'une thrombopénie est un <strong>syndrome hémorragique cutanéo-muqueux</strong>.</p>"},{"i":"cba13b59cce4","n":214,"o":"214-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux thrombopénies","q":"Dans quelles situations rares une thrombopénie chez l'adulte et l'enfant peut-elle se révéler par une manifestation thrombotique ?","a":"<p>La thrombopénie peut être révélée par une manifestation thrombotique (le plus souvent sans syndrome hémorragique) dans les cas de :</p><ul><li>Thrombopénie induite par l'héparine (<strong>TIH de type 2</strong>)</li><li>Microangiopathies thrombotiques (<strong>MAT</strong>), notamment Purpura Thrombotique Thrombopénique (<strong>PTT</strong>) et Syndrome Hémolytique et Urémique (<strong>SHU</strong>)</li><li>Syndrome des antiphospholipides (<strong>SAPL</strong>)</li><li>Coagulation Intravasculaire Disséminée (<strong>CIVD</strong>)</li></ul>"},{"i":"fb147e878ed0","n":214,"o":"214-3","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux thrombopénies","q":"Quelles sont les manifestations hémorragiques cutanées et muqueuses typiques d'une thrombopénie chez l'adulte et l'enfant ?","a":"<ul><li><strong>Saignements cutanés</strong> : <ul><li>Purpura thrombopénique (pétéchial et/ou ecchymotique)</li><li>Hématomes</li></ul></li><li><strong>Saignements muqueux</strong> : <ul><li>Épistaxis</li><li>Gingivorragies (spontanées ou au brossage)</li><li>Bulles hémorragiques intra-buccales et purpura du voile du palais</li><li>Hémorragies digestives (méléna, rectorragies, plus rarement hématémèse)</li><li>Méno-métrorragies</li><li>Hématurie</li></ul></li></ul>"},{"i":"1d78100585e2","n":214,"o":"214-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura thrombopénique","q":"Quelles sont les caractéristiques sémiologiques d'un purpura thrombopénique à l'examen clinique ?","a":"<ul><li><strong>Aspect</strong> : <strong>Monomorphe</strong>, pétéchial et/ou ecchymotique.</li><li><strong>Relief</strong> : <strong>Non infiltré</strong> (plan, ne se palpe pas).</li><li><strong>Topographie</strong> : <strong>Diffus</strong>, à prédominance cutanée, avec hématomes possibles.</li><li><strong>Survenue</strong> : <strong>Spontanée</strong>, sans facteur déclenchant.</li></ul>"},{"i":"6ccbed69f577","n":214,"o":"214-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura thrombopénique","q":"Quel est l'élément sémiologique discriminant qui différencie un purpura thrombopénique d'un purpura vasculaire ?","a":"<p>L'élément discriminant est le caractère <strong>non infiltré</strong> du purpura thrombopénique, par opposition au purpura vasculaire qui est <strong>infiltré et palpable</strong>.</p>"},{"i":"6f8d44a779b8","n":214,"o":"214-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura thrombopénique","q":"Quel type de purpura thrombopénique doit faire craindre une forme grave et impose une évaluation en urgence ?","a":"<p>Un <strong>purpura ecchymotique extensif, disséminé, voire nécrotique</strong> est un signe de gravité et impose une évaluation en urgence.</p>"},{"i":"8975a9c75621","n":214,"o":"214-4","u":"Diagnostic positif","t":"Connaître les caractéristiques cliniques d’un purpura thrombopénique","q":"Comment définir cliniquement le purpura thrombopénique ?","a":"<p>Le purpura thrombopénique correspond à l'<strong>extravasation spontanée des globules rouges</strong> dans le tissu sous-cutané ou le chorion.</p>"},{"i":"2d6d203a80f2","n":214,"o":"214-6","u":"Contenu multimédia","t":"Photographie d’une bulle intrabuccale","q":"Quelle est la caractéristique d'une bulle intrabuccale associée à une thrombopénie ?","a":"<p>La bulle intrabuccale est typiquement de nature <strong>hémorragique</strong> et se situe sur la face interne des joues, le palais ou la langue.</p>"},{"i":"bc83d1736ee1","n":214,"o":"214-6","u":"Contenu multimédia","t":"Photographie d’une bulle intrabuccale","q":"Quel score intègre les bulles intrabuccales dans l'évaluation d'un syndrome hémorragique ?","a":"<p>Les bulles intrabuccales sont intégrées au score de <strong>Buchanan</strong>, un score hémorragique pédiatrique utilisé notamment dans le cadre du Purpura Thrombopénique Immunologique (PTI). Dans ce score, la rubrique « Bouche » évalue la présence de bulles et leur éventuel saignement actif.</p>"},{"i":"ee4aad467c5a","n":214,"o":"214-6","u":"Contenu multimédia","t":"Photographie d’une bulle intrabuccale","q":"Quelle sévérité de thrombopénie est suggérée par la présence de bulles hémorragiques intrabuccales ?","a":"<p>La présence de bulles hémorragiques intrabuccales est un signe de <strong>thrombopénie profonde</strong>, généralement inférieure à <strong>20 G/L</strong>. Elle est considérée comme <strong>pathognomonique d'une thrombopénie sévère</strong>.</p>"},{"i":"1e1da165aaf9","n":214,"o":"214-7","u":"Identifier une urgence","t":"Connaître les signes de gravité et les urgences vitales devant une thrombopénie","q":"Dans le cadre du Purpura Thrombopénique Immunologique (PTI), quelles sont les deux conditions qui définissent une urgence thérapeutique ?","a":"<p>Dans le PTI, une urgence thérapeutique est définie par l'association d'une <strong>thrombopénie &lt; 30 G/L</strong> et d'un score hémorragique élevé (<strong>Khellaf ≥ 8</strong> ou <strong>Buchanan &gt; 3</strong>).</p>"},{"i":"2b0f8c803c9a","n":214,"o":"214-7","u":"Identifier une urgence","t":"Connaître les signes de gravité et les urgences vitales devant une thrombopénie","q":"Quelle est la définition d'une thrombopénie grave chez l'adulte et l'enfant, au-delà de la profondeur de la thrombopénie simple ?","a":"<p>Une thrombopénie est considérée comme grave, exposant à un risque hémorragique spontané, en fonction de trois ordres de facteurs :</p><ul><li><strong>Biologique</strong> : thrombopénie &lt; 20 G/L ou risque hémorragique plus élevé si origine centrale (par rapport à périphérique) à chiffre égal.</li><li><strong>Contextuel/terrain</strong> : âge &gt; 65 ans, comorbidités hémorragiques, existence d'une lésion susceptible de saigner (site opératoire, ulcère gastroduodénal, lésion tumorale), ou prise de traitements interférant avec l'hémostase (AINS, ISRS, anticoagulants).</li><li><strong>Clinique</strong> : présence de signes hémorragiques.</li></ul>"},{"i":"3feb93882093","n":214,"o":"214-7","u":"Identifier une urgence","t":"Connaître les signes de gravité et les urgences vitales devant une thrombopénie","q":"Quels sont les signes cliniques qui doivent faire suspecter une thrombopénie grave chez l'adulte et l'enfant ?","a":"<p>Les signes cliniques de thrombopénie grave incluent :</p><ul><li>Un <strong>purpura ecchymotique extensif/nécrotique</strong>.</li><li>Des <strong>hématomes spontanés confluents</strong> (notamment au niveau des membres supérieurs et du tronc).</li><li>Des <strong>saignements muqueux graves</strong> : bulles hémorragiques intra-buccales, épistaxis bilatérale, gingivorragies spontanées, méno-métrorragies, hématurie macroscopique, hémorragie digestive, hémorragies au fond d'œil.</li><li>Tout saignement avec <strong>déglobulisation</strong>.</li></ul>"},{"i":"9ca72bd3d489","n":214,"o":"214-7","u":"Identifier une urgence","t":"Connaître les signes de gravité et les urgences vitales devant une thrombopénie","q":"Quel signe neurologique impose une imagerie cérébrale en urgence devant une thrombopénie, et pourquoi ?","a":"<p>Tout signe neurologique, même isolé (comme des <strong>céphalées</strong>, une <strong>confusion</strong>, un <strong>coma</strong>, ou un <strong>déficit neurologique</strong>), doit faire craindre une <strong>hémorragie cérébro-méningée</strong>. Cela impose la réalisation d'une <strong>imagerie cérébrale en urgence</strong> (TDM) car il s'agit d'une urgence vitale.</p>"},{"i":"009117d3f469","n":214,"o":"214-8","u":"Diagnostic positif","t":"Savoir reconnaître une fausse thrombopénie","q":"Quelle est la conduite à tenir face à une suspicion de fausse thrombopénie ?","a":"<p>La démarche est la suivante :</p><ul><li>Réaliser un <strong>frottis sanguin</strong> pour rechercher des agrégats plaquettaires ou un satellitisme. La simple visualisation de ces phénomènes suffit à affirmer la fausse thrombopénie.</li><li>Effectuer un nouveau prélèvement sanguin sur un tube <strong>citraté</strong> (le citrate chélatant le calcium et prévenant l'agrégation), voire sur tube hépariné, tube capillaire ou micro-méthode.</li></ul>"},{"i":"15c2e1f3f60e","n":214,"o":"214-8","u":"Diagnostic positif","t":"Savoir reconnaître une fausse thrombopénie","q":"Quand suspecter une fausse thrombopénie chez un patient ?","a":"<p>Il faut rechercher une fausse thrombopénie devant toute <strong>thrombopénie sans signe hémorragique cutanéo-muqueux</strong>. Elle ne doit pas être recherchée en présence d'un syndrome hémorragique authentique.</p>"},{"i":"24be5ce7963c","n":214,"o":"214-8","u":"Diagnostic positif","t":"Savoir reconnaître une fausse thrombopénie","q":"Comment définir une fausse thrombopénie ou pseudo-thrombopénie ?","a":"<p>Une fausse thrombopénie est un <strong>artéfact pré-analytique</strong>, le plus souvent lié à l'utilisation du tube <strong>EDTA</strong> (Ethylène Diamine Tétra-Acétate) lors du prélèvement sanguin.</p>"},{"i":"fccb793d30e9","n":214,"o":"214-8","u":"Diagnostic positif","t":"Savoir reconnaître une fausse thrombopénie","q":"Quel est le piège classique lié à l'utilisation du tube citraté pour confirmer une fausse thrombopénie ?","a":"<p>Sur un <strong>tube citraté</strong>, le résultat du comptage plaquettaire peut être <strong>sous-estimé d'environ 10 % par dilution</strong>. Il est donc important d'en tenir compte lors de l'interprétation des résultats.</p>"},{"i":"ff300052997f","n":214,"o":"214-8","u":"Diagnostic positif","t":"Savoir reconnaître une fausse thrombopénie","q":"Quels mécanismes entraînent une fausse thrombopénie liée à l'EDTA ?","a":"<p>L'EDTA peut induire <em>in vitro</em> deux phénomènes principaux :</p><ul><li>Des <strong>amas plaquettaires</strong> (agrégation des plaquettes entre elles).</li><li>Le <strong>satellitisme</strong> (formation de rosettes de plaquettes autour des polynucléaires).</li></ul>"},{"i":"732f758dce58","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie par défaut de production (centrales) chez l'adulte et l'enfant ?","a":"<p>Les principales étiologies des thrombopénies centrales sont :</p><ul><li>Les <strong>envahissements médullaires</strong> (tumeurs), la <strong>myélofibrose</strong>, les <strong>myélodysplasies</strong>.</li><li>L'<strong>aplasie médullaire</strong> (idiopathique, toxique, médicamenteuse).</li><li>Les <strong>mégaloblastoses</strong> par carence en <strong>vitamine B9 ou B12</strong>.</li><li>L'<strong>alcoolisme chronique</strong>.</li><li>Les <strong>thrombopénies constitutionnelles</strong> : syndrome de <strong>Wiskott-Aldrich</strong>, syndromes <strong>MYH9</strong> (May-Hegglin), <strong>amégacaryocytoses congénitales</strong>.</li></ul>"},{"i":"839f847716fd","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie les plus fréquentes ou à évoquer en priorité chez l'adulte ?","a":"<p>Chez l'adulte, on évoque davantage :</p><ul><li>Les causes <strong>médicamenteuses</strong>.</li><li>L'<strong>alcoolisme</strong>.</li><li>Les <strong>hémopathies</strong>, notamment le syndrome myélodysplasique après 50 ans.</li></ul>"},{"i":"9227a15b416e","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie par destruction périphérique chez l'adulte et l'enfant ?","a":"<p>Les principales étiologies des thrombopénies périphériques par destruction sont :</p><ul><li>Le <strong>Purpura Thrombopénique Immunologique (PTI)</strong>, qui est un diagnostic d'élimination.</li><li>Les <strong>maladies auto-immunes</strong> : <strong>Lupus</strong>, <strong>SAPL</strong> (syndrome des antiphospholipides), syndrome d'<strong>Evans</strong> (anémie hémolytique auto-immune + PTI).</li><li>Les <strong>hémopathies</strong> : <strong>LLC</strong> (leucémie lymphoïde chronique), certains <strong>déficits immunitaires</strong> (DICV).</li><li>Les <strong>infections virales</strong> : <strong>VIH</strong>, <strong>VHC</strong>, <strong>VHB</strong>, <strong>EBV</strong>, <strong>CMV</strong>, <strong>parvovirus B19</strong>.</li><li>Les mécanismes multiples (souvent associé à une destruction) : <strong>paludisme</strong>, <strong>dengue</strong>, <strong>sepsis</strong>.</li><li>Les thrombopénies <strong>immuno-allergiques médicamenteuses</strong> : <strong>TIH (héparine)</strong>, <strong>quinine</strong>, <strong>thiazidiques</strong>, <strong>AINS</strong>, <strong>antibiotiques</strong> (cotrimoxazole, rifampicine, bêta-lactamines).</li></ul>"},{"i":"b982e260b9ba","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie les plus fréquentes ou à évoquer en priorité chez l'enfant ?","a":"<p>Chez l'enfant, le terrain oriente vers :</p><ul><li>Le <strong>PTI aigu post-viral</strong>.</li><li>Le <strong>SHU typique post-diarrhéique</strong>.</li><li>Les <strong>thrombopénies constitutionnelles</strong>.</li></ul>"},{"i":"bfdafaf6efca","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie par consommation périphérique chez l'adulte et l'enfant ?","a":"<p>Les principales étiologies des thrombopénies périphériques par consommation sont :</p><ul><li>La <strong>CIVD</strong> (coagulation intravasculaire disséminée).</li><li>Les <strong>microangiopathies thrombotiques (MAT)</strong> : Purpura Thrombotique Thrombocytopénique (<strong>PTT</strong>) et Syndrome Hémolytique et Urémique (<strong>SHU</strong>).</li><li>Autres : <strong>prothèses valvulaires</strong>, <strong>CEC</strong> (circulation extracorporelle), syndrome de <strong>Kasabach-Merritt</strong>.</li></ul>"},{"i":"f8076bcc14db","n":214,"o":"214-9","u":"Étiologies","t":"Connaître les principales causes de thrombopénie chez l’enfant et l’adulte","q":"Quelles sont les causes de thrombopénie par hyperséquestration ou dilution chez l'adulte et l'enfant ?","a":"<p>Les causes de thrombopénie par hyperséquestration ou dilution sont :</p><ul><li>L'<strong>hypersplénisme</strong>, entraînant une séquestration plaquettaire splénique.</li><li>La <strong>dilution</strong> due à des <strong>transfusions ou perfusions massives</strong>.</li></ul>"}]};